import numpy as np
from numba import njit

@njit(cache=True)
def _auction(c):
    n=c.shape[0]; p=np.zeros(n); ans=np.empty(n,np.int32); own=np.empty(n,np.int32)
    q=np.empty(10000000,np.int32)
    eps=.1
    while eps>1e-11:
        for j in range(n): own[j]=-1
        head=0;tail=n
        for i in range(n):q[i]=i
        while head<tail:
            i=q[head];head+=1; x=1e100;y=1e100;bj=-1
            for j in range(n):
                v=c[i,j]+p[j]
                if v<x:y=x;x=v;bj=j
                elif v<y:y=v
            p[bj]+=y-x+eps
            old=own[bj];own[bj]=i;ans[i]=bj
            if old>=0:q[tail]=old;tail+=1
        eps*=.1
    return ans

class Solver:
 def solve(self,problem,**kwargs):
    M=np.asarray(problem['cost_matrix']); c=_auction(M); n=M.shape[0]
    G=np.zeros(M.shape);G[np.arange(n),c]=np.asarray(problem['source_weights'])
    return {'transport_plan':G}
